CREATE VIEW [FO].[vwLedgerTransbyAccount] AS

WITH 
VDU AS (
	SELECT
		VOUCHER
	,COUNT(DISTINCT ACCOUNTNUM) DupCount
	FROM [synapse_fo].[CUSTTRANS_RICS]
	GROUP BY VOUCHER
	HAVING COUNT(DISTINCT ACCOUNTNUM) > 1
),

VDUP AS (
	SELECT 
	 CTR.ACCOUNTNUM
	FROM [synapse_fo].[CUSTTRANS_RICS] CTR
	INNER JOIN VDU ON VDU.VOUCHER = CTR.VOUCHER
	GROUP BY CTR.ACCOUNTNUM
),

cte AS (
	SELECT
	ACCOUNTNUM,
	VOUCHER
	FROM [synapse_fo].[CUSTTRANS_RICS]
	--WHERE ACCOUNTNUM = 000000 --000000
	GROUP BY
	ACCOUNTNUM,
	VOUCHER
)

SELECT 
	c1.ACCOUNTNUM,	
	LT.[RECID],
	LT.[GENERALJOURNALENTRY],
	LT.[ACCOUNTDISPLAYVALUE],
	--LT.[LEDGERACCOUNT],
	LT.[JOURNALNUMBER],
	LT.[SUBLEDGERVOUCHER],
	LT.[ACCOUNTINGDATE],
	--LT.[POSTINGLAYER],
	LT.[TRANSACTIONCURRENCYCODE],
	LT.[TRANSACTIONCURRENCYAMOUNT],
	LT.[ACCOUNTINGCURRENCYAMOUNT],
	LT.[REPORTINGCURRENCYAMOUNT],
	--LT.[DESCRIPTION],
	--LT.[QUANTITY],
	LT.[POSTINGTYPE],
	LT.[JOURNALCATEGORY],
	LT.[ISCORRECTION],
	LT.[ISCREDIT],
	LT.[ACKNOWLEDGEMENTDATE],
	LT.[DOCUMENTDATE],
	LT.[DOCUMENTNUMBER],
	--LT.[LEDGERNAME],
	LT.[MAINACCOUNT],
	LT.[TEXT],
	--LT.[ALLOCATIONLEVEL],
	LT.[PAYMENTREFERENCE],
	LT.[REASONREF],
	LT.[DATAAREAID],
	LT.[RICSCOSTCENTER] AS [COSTCENTER],
	LT.[RICSCAMPAIGNYEAR] AS [CAMPAIGNYEAR],
	--LT.[RICSCHANNEL] AS [CHANNEL],
	LT.[RICSCOUNTRY] AS [COUNTRY],
	--LT.[RICSCUSTOMER] AS [CUSTOMER],
	--LT.[RICSENTITY] AS [ENTITY],
	LT.[RICSFIXEDASSETGROUP] AS [FIXEDASSETGROUP],
	--LT.[RICSFUNCTION],
	LT.[RICSINTERCOMPANY] AS [INTERCOMPANY],
	LT.[RICSINTERIMREPORTINGENTITY] AS [INTERIMREPORTINGENTITY],
	--LT.[RICSLOCATION],
	--LT.[RICSNEW_RENEWAL] AS [NEW_RENEWAL],
	LT.[RICSPRODUCTCODE] AS [PRODUCTCODE],
	LT.[RICSPRODUCTGROUP] AS [PRODUCTGROUP],
	LT.[RICSPROJECT] AS [PROJECT],
	LT.[CREATEDBY1],
	LT.[CREATEDDATETIME1],
	LT.TB_Category_Code,
	LT.[SUBLEDGERVOUCHER] AS [VOUCHER],
	LT.[RECID] AS [GENERALJOURNALACCOUNTENTRYRECID]
FROM [synapse_fo].[LEDGERTRANS_RICS] LT --FO.[vwLedgerTrans] LT
	INNER JOIN cte AS C1 ON LT.SUBLEDGERVOUCHER = C1.VOUCHER
	LEFT JOIN VDUP AS VDUP ON VDUP.ACCOUNTNUM = C1.ACCOUNTNUM
WHERE 1=1
	AND MAINACCOUNT IN ('000000')
	AND VDUP.ACCOUNTNUM IS NULL
	AND LT.SUBLEDGERVOUCHER NOT LIKE 'YE2%'
--AND LT.VOUCHER IN ('RCS-GJ000000', 'RCS000000')
